    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        count = Counter(nums)
        result = None
        for x in nums:
            outlier = total - 2 * x
            if outlier == x:
                if count[outlier] >= 2:
                    if result is None or outlier > result:
                        result = outlier
            else:
                if count[outlier] >= 1:
                    if result is None or outlier > result:
                        result = outlier
        return result
